{$ param month label="Month Abbrev" default="APR" description="Three-letter month shown in the date badge." $}
{$ param year label="Year" default="2025" description="Year shown in the badge." $}
{$ param time label="Time" default="7pm EST" description="Time displayed under the date." $}
{$ param tag label="Tag" default="Zoom" description="Location or format tag." $}
{$ param video_embed_url label="Video Embed URL" default="" description="Optional iframe src for an embedded recording." type="fileurl" $}
{$ param video_title label="Video Title" default="Event recording" description="Accessible title for the video iframe." $}
{$ param title label="Event Title" default="Event Name" description="Event heading." $}
{$ param date_line label="Date Line" default="April 10, 2025 · 7pm to 9pm EST" description="Human-readable date/time line." $}
{$ param location_line label="Location Line" default="" description="Where the event happened (optional)." $}
{$ param primary_href label="Primary URL" default="#" description="First follow-up link (e.g. featured project)." $}
{$ param primary_label label="Primary Label" default="Featured: Project Name" description="First button text." $}
{$ param secondary_href label="Secondary URL" default="" description="Second follow-up link (optional)." $}
{$ param secondary_label label="Secondary Label" default="Learn More" description="Second button text." $}

<div class="ss-ec ss-ec-archived mb-4">
  <div class="ss-ec-info">
    <div><span class="cc-ec-info-month">{$= month $}</span> <span class="cc-ec-info-year">{$= year $}</span></div>
    <div class="cc-ec-info-time">{$= time $}</div>
    <div class="ss-ec-tag"><span>{$= tag $}</span></div>
    {$ if video_embed_url $}<div class="aspect-[16/9] w-full">
      <iframe src="{$= video_embed_url $}" title="{$= video_title $}" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
    </div>{$ /if $}
  </div>
  <div class="ss-ec-content">
    <h3><a href="{$= primary_href $}">{$= title $}</a></h3>
    <h4>{$= date_line $}</h4>
    {$ if location_line $}<div class="ss-ec-loc">{$= location_line $}</div>{$ /if $}
    {$ slot description $}
      <p>Event description.</p>
    {$ /slot $}
    <a href="{$= primary_href $}" class="btn btn-primary">{$= primary_label $}</a>
    {$ if secondary_href $}<a href="{$= secondary_href $}" class="btn btn-secondary">{$= secondary_label $}</a>{$ /if $}
  </div>
</div>
